import assert from 'node:assert/strict';import {mkdir,readFile} from 'node:fs/promises';import {chromium} from 'playwright';import {installConnectedFixture,signInFixture} from './connected-fixture.mjs';
const browser=await chromium.launch({args:['--no-sandbox']});await mkdir('ui-renders',{recursive:true});
try{for(const width of [360,390,430]){
 const context=await browser.newContext({viewport:{width,height:844}});await installConnectedFixture(context);
 // New hosted thumbnails may not be deployed while reviewing this PR.
 await context.route('https://tradeblackbook.org/public/assets/indices/**',async route=>{const name=new URL(route.request().url()).pathname;try{await route.fulfill({body:await readFile('../index-frontend/apps/web'+name),contentType:name.endsWith('.svg')?'image/svg+xml':'image/webp'});}catch{await route.fulfill({status:204});}});
 const page=await context.newPage();await page.goto('http://127.0.0.1:4173/',{waitUntil:'networkidle'});assert.doesNotMatch(await page.locator('body').innerText(),/No trading/);await page.screenshot({path:`ui-renders/review-guest-${width}.png`,fullPage:true});
 await signInFixture(page);await page.goto('http://127.0.0.1:4173/profile',{waitUntil:'networkidle'});await page.getByText('Account mode',{exact:true}).waitFor();const profile=await page.locator('body').innerText();assert.doesNotMatch(profile,/Equity|Available|Unrealized P&L|Realized P&L|Deposit|Withdraw|Payment history/);await page.screenshot({path:`ui-renders/review-profile-${width}.png`,fullPage:true});
 await page.goto('http://127.0.0.1:4173/indices',{waitUntil:'networkidle'});await page.getByText('Coming soon',{exact:true}).first().click();await page.getByText('LeBron James',{exact:true}).waitFor();await page.screenshot({path:`ui-renders/review-coming-${width}.png`,fullPage:true});
 await page.goto('http://127.0.0.1:4173/feed',{waitUntil:'networkidle'});await page.getByText('Guides',{exact:true}).click();await page.getByText('Perpetual Trading · No Funding Rate',{exact:true}).waitFor();assert.doesNotMatch(await page.locator('body').innerText(),/Available indices/);
 await page.getByText('Movers',{exact:true}).click();await page.getByText('Highest volume',{exact:true}).waitFor();await page.getByText('Most volatile',{exact:true}).waitFor();assert.doesNotMatch(await page.locator('body').innerText(),/density|Widest active bands/i);
 await context.close();console.log(`review ${width}: guest mini charts, clean profile, NBA coming soon and guides/movers passed`);
}
const context=await browser.newContext({viewport:{width:390,height:844}});await installConnectedFixture(context);const page=await context.newPage();await page.goto('http://127.0.0.1:4173/',{waitUntil:'networkidle'});await page.getByRole('button',{name:'Sign in',exact:true}).click();await page.getByRole('button',{name:'Create account',exact:true}).click();await page.setViewportSize({width:390,height:390});await page.getByLabel('Password',{exact:true}).focus();await page.waitForTimeout(400);const box=await page.getByLabel('Password',{exact:true}).boundingBox();assert.ok(box.y>=0&&box.y+box.height<=390);await page.screenshot({path:'ui-renders/review-keyboard-viewport.png',fullPage:true});await context.close();
}finally{await browser.close();}
